begin;
create table public.game_bank(id uuid primary key default gen_random_uuid(),subject_code text not null references public.subjects(code),topic_id uuid not null,prompt text not null,choices jsonb not null check(jsonb_typeof(choices)='array' and jsonb_array_length(choices)=4),correct_choice_id text not null,explanation text not null,origin text not null default 'original_ai' check(origin='original_ai'),verification jsonb not null,content_hash text not null unique check(content_hash ~ '^[a-f0-9]{64}$'),foreign key(topic_id,subject_code) references public.topics(id,subject_code));
create table public.game_rooms(id uuid primary key default gen_random_uuid(),host_id uuid not null references auth.users(id) on delete cascade,guest_id uuid not null references auth.users(id) on delete cascade,programme_key text not null references public.science_programmes(programme_key),subject_code text not null references public.subjects(code),mode text not null check(mode in('quickfire','cooperative')),status text not null default 'waiting' check(status in('waiting','ready','active','finished','cancelled')),host_ready boolean not null default false,guest_ready boolean not null default false,question_count integer not null check(question_count between 3 and 20),round_seconds integer not null check(round_seconds between 10 and 60),current_round integer not null default 0 check(current_round between 0 and 20),created_at timestamptz not null default now(),check(host_id<>guest_id));
create table public.game_rounds(room_id uuid not null references public.game_rooms(id) on delete cascade,number integer not null,question_id uuid not null references public.game_bank(id),status text not null default 'pending' check(status in('pending','active','closed')),starts_at timestamptz,deadline timestamptz,closed_at timestamptz,winner uuid references auth.users(id) on delete set null,primary key(room_id,number),unique(room_id,question_id),check(number between 1 and 20),check(status='pending' or(starts_at is not null and deadline is not null and deadline>starts_at)));
create table public.game_answers(room_id uuid not null,round_number integer not null,player_id uuid not null references auth.users(id) on delete cascade,choice_id text not null,correct boolean not null,submitted_at timestamptz not null default clock_timestamp(),primary key(room_id,round_number,player_id),foreign key(room_id,round_number) references public.game_rounds(room_id,number) on delete cascade);
do $$declare t text;begin foreach t in array array['game_bank','game_rooms','game_rounds','game_answers'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant all on public.%I to service_role',t);end loop;end $$;
grant select on public.game_rooms to authenticated;create policy room_participant on public.game_rooms for select to authenticated using((select public.revision_actor()) in(host_id,guest_id));create index game_host_idx on public.game_rooms(host_id,created_at desc);create index game_guest_idx on public.game_rooms(guest_id,created_at desc);
create function public.validate_game_bank() returns trigger language plpgsql security definer set search_path='' as $$begin
if TG_OP='UPDATE' and new is distinct from old then raise exception 'GAME_ITEM_IMMUTABLE';end if;
if not exists(select 1 from public.topics where id=new.topic_id and verified and kind='objective') or not(new.verification @> '{"scientific_status":"pass","mark_scheme_status":"pass","originality_status":"pass"}') or new.verification->>'model' is null or new.verification->>'generator_model' is null or new.verification->>'model'=new.verification->>'generator_model' then raise exception 'GAME_ITEM_NOT_VERIFIED';end if;
if(select count(distinct value->>'id') from jsonb_array_elements(new.choices))<>4 or not exists(select 1 from jsonb_array_elements(new.choices) where value->>'id'=new.correct_choice_id) or exists(select 1 from jsonb_array_elements(new.choices) where jsonb_typeof(value)<>'object' or(value-'id'-'text')<>'{}'::jsonb or length(trim(coalesce(value->>'id',''))) not between 1 and 2 or length(trim(coalesce(value->>'text',''))) not between 1 and 1000) then raise exception 'GAME_CHOICES_INVALID';end if;return new;end $$;
create trigger game_bank_validation before insert or update on public.game_bank for each row execute function public.validate_game_bank();
create function public.publish_game_question_job(p_id uuid,p_worker uuid,p_attempt integer,p_count integer) returns jsonb language plpgsql security definer set search_path='' as $$declare j public.jobs;result jsonb;a record;q jsonb;begin
j:=public.assert_revision_lease(p_id,p_worker,p_attempt);if j.kind<>'generate_question' or j.payload->>'purpose' is distinct from 'game' or j.payload ? 'extracted_id' then raise exception 'INVALID_GAME_GENERATION';end if;
result:=public.publish_question_job(p_id,p_worker,p_attempt,p_count);
for a in select * from public.job_artifacts where job_id=j.id and item_index between 0 and p_count-1 loop q:=a.data->'packet'->'question';if q->>'format'<>'multiple_choice' or(q->>'marks')::integer<>1 then raise exception 'INVALID_GAME_ITEM';end if;insert into public.game_bank(subject_code,topic_id,prompt,choices,correct_choice_id,explanation,verification,content_hash) values(q->>'subject_code',(q->>'topic_id')::uuid,q->>'prompt',q->'choices',q->>'correct_choice_id',q->>'examiner_explanation',a.data->'verification',a.data->>'content_hash') on conflict(content_hash) do nothing;end loop;return result;end $$;
create function public.create_game(p_guest uuid,p_subject text,p_mode text,p_count integer default 5,p_seconds integer default 20) returns uuid language plpgsql security definer set search_path='' as $$declare actor uuid:=public.revision_actor();a text;b text;rid uuid;begin
if actor is null or not exists(select 1 from public.friendships where user_low=least(actor,p_guest) and user_high=greatest(actor,p_guest) and status='accepted') then raise exception 'ACCEPTED_FRIEND_REQUIRED';end if;
select programme_key into a from public.profiles where user_id=actor and account_state='active';select programme_key into b from public.profiles where user_id=p_guest and account_state='active';if a is null or b is null then raise exception 'SELECT_COURSE_FIRST';end if;
if p_mode is null or p_mode not in('quickfire','cooperative') or p_count is null or p_count not between 3 and 20 or p_seconds is null or p_seconds not between 10 and 60 then raise exception 'INVALID_GAME_OPTIONS';end if;if not public.consume_revision_usage(actor,'friend_games',20) then raise exception 'GAME_LIMIT';end if;
insert into public.game_rooms(host_id,guest_id,programme_key,subject_code,mode,question_count,round_seconds) values(actor,p_guest,case when a='double_award' or b='double_award' then 'double_award' else 'separate_sciences' end,p_subject,p_mode,p_count,p_seconds) returning id into rid;return rid;end $$;
create function public.ready_game(p_room uuid) returns boolean language plpgsql security definer set search_path='' as $$declare actor uuid:=public.revision_actor();g public.game_rooms;begin
select * into g from public.game_rooms where id=p_room and actor in(host_id,guest_id) for update;if not found or g.status not in('waiting','ready') then raise exception 'GAME_NOT_AVAILABLE';end if;
if actor=g.host_id then update public.game_rooms set host_ready=true where id=p_room;else update public.game_rooms set guest_ready=true where id=p_room;end if;update public.game_rooms set status='ready' where id=p_room and host_ready and guest_ready;return true;end $$;
create function public.start_game(p_room uuid) returns boolean language plpgsql security definer set search_path='' as $$declare actor uuid:=public.revision_actor();g public.game_rooms;n integer;t timestamptz;begin
select * into g from public.game_rooms where id=p_room and host_id=actor for update;if not found then raise exception 'GAME_NOT_FOUND';end if;if g.status='active' then return true;end if;if g.status<>'ready' or not(g.host_ready and g.guest_ready) then raise exception 'BOTH_PLAYERS_MUST_BE_READY';end if;
if not exists(select 1 from public.friendships where user_low=least(g.host_id,g.guest_id) and user_high=greatest(g.host_id,g.guest_id) and status='accepted') then raise exception 'ACCEPTED_FRIEND_REQUIRED';end if;
insert into public.game_rounds(room_id,number,question_id) select p_room,row_number() over()::integer,q.id from(select b.id from public.game_bank b join public.topics t on t.id=b.topic_id where b.subject_code=g.subject_code and t.verified and t.kind='objective' and(g.programme_key='separate_sciences' or t.scope='core') order by random() limit g.question_count) q;
get diagnostics n=row_count;if n<>g.question_count then raise exception 'VALIDATED_QUESTION_BANK_NOT_READY';end if;t:=clock_timestamp();update public.game_rounds set status='active',starts_at=t+interval '3 seconds',deadline=t+(3+g.round_seconds)*interval '1 second' where room_id=p_room and number=1;update public.game_rooms set status='active',current_round=1 where id=p_room;return true;end $$;
create function public.answer_game(p_room uuid,p_choice text) returns jsonb language plpgsql security definer set search_path='' as $$declare actor uuid:=public.revision_actor();g public.game_rooms;r public.game_rounds;q public.game_bank;correct boolean;t timestamptz;n integer;begin
select * into g from public.game_rooms where id=p_room and actor in(host_id,guest_id) for update;if not found or g.status<>'active' then raise exception 'GAME_NOT_ACTIVE';end if;select * into r from public.game_rounds where room_id=p_room and number=g.current_round for update;t:=clock_timestamp();if r.status<>'active' or t>=r.deadline then raise exception 'ROUND_CLOSED';end if;if t<r.starts_at then raise exception 'ROUND_NOT_STARTED';end if;
if exists(select 1 from public.game_answers where room_id=p_room and round_number=g.current_round and player_id=actor) then raise exception 'ANSWER_ALREADY_SUBMITTED';end if;select * into q from public.game_bank where id=r.question_id;if p_choice is null or not exists(select 1 from jsonb_array_elements(q.choices) where value->>'id'=p_choice) then raise exception 'INVALID_CHOICE';end if;correct:=p_choice=q.correct_choice_id;insert into public.game_answers values(p_room,g.current_round,actor,p_choice,correct,t);select count(*) into n from public.game_answers where room_id=p_room and round_number=g.current_round;
if(g.mode='quickfire' and correct) or n=2 then update public.game_rounds set status='closed',closed_at=t,winner=case when g.mode='quickfire' and correct then actor else null end where room_id=p_room and number=g.current_round;end if;perform public.record_study_activity(actor);return jsonb_build_object('accepted',true,'round_closed',(g.mode='quickfire' and correct) or n=2);end $$;
create function public.next_game(p_room uuid) returns boolean language plpgsql security definer set search_path='' as $$declare actor uuid:=public.revision_actor();g public.game_rooms;r public.game_rounds;t timestamptz;begin
select * into g from public.game_rooms where id=p_room and actor in(host_id,guest_id) for update;if not found then raise exception 'GAME_NOT_FOUND';end if;if g.status='finished' then return true;end if;if g.status<>'active' then raise exception 'GAME_NOT_ACTIVE';end if;select * into r from public.game_rounds where room_id=p_room and number=g.current_round for update;t:=clock_timestamp();if r.status='active' and t<r.deadline then raise exception 'ROUND_STILL_ACTIVE';end if;if r.status='closed' and t<r.closed_at+interval '2 seconds' then raise exception 'FEEDBACK_PAUSE';end if;update public.game_rounds set status='closed',closed_at=coalesce(closed_at,t) where room_id=p_room and number=g.current_round;
if g.current_round>=g.question_count then update public.game_rooms set status='finished' where id=p_room;return true;end if;update public.game_rooms set current_round=current_round+1 where id=p_room;update public.game_rounds set status='active',starts_at=t+interval '3 seconds',deadline=t+(3+g.round_seconds)*interval '1 second' where room_id=p_room and number=g.current_round+1;return true;end $$;
create function public.game_snapshot(p_room uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare actor uuid:=public.revision_actor();g public.game_rooms;r public.game_rounds;q public.game_bank;closed boolean;scores jsonb;choices jsonb;begin
select * into g from public.game_rooms where id=p_room and actor in(host_id,guest_id);if not found then raise exception 'GAME_NOT_FOUND';end if;
select jsonb_object_agg(p.id::text,case when g.mode='quickfire' then(select count(*) from public.game_rounds x where x.room_id=p_room and x.winner=p.id) else(select count(*) from public.game_answers a join public.game_rounds x on x.room_id=a.room_id and x.number=a.round_number where a.room_id=p_room and a.player_id=p.id and a.correct and(x.status='closed' or x.deadline<=clock_timestamp())) end) into scores from(values(g.host_id),(g.guest_id)) p(id);
if g.current_round=0 then return jsonb_build_object('id',g.id,'status',g.status,'mode',g.mode,'programme_key',g.programme_key,'host_id',g.host_id,'guest_id',g.guest_id,'host_ready',g.host_ready,'guest_ready',g.guest_ready,'scores',scores,'server_now',clock_timestamp());end if;
select * into r from public.game_rounds where room_id=p_room and number=g.current_round;select * into q from public.game_bank where id=r.question_id;closed:=r.status='closed' or r.deadline<=clock_timestamp();select jsonb_agg(jsonb_build_object('id',value->>'id','text',value->>'text')) into choices from jsonb_array_elements(q.choices);
return jsonb_build_object('id',g.id,'status',g.status,'mode',g.mode,'programme_key',g.programme_key,'host_id',g.host_id,'guest_id',g.guest_id,'round',g.current_round,'question_count',g.question_count,'starts_at',r.starts_at,'deadline',r.deadline,'server_now',clock_timestamp(),'prompt',q.prompt,'choices',choices,'answered',exists(select 1 from public.game_answers where room_id=p_room and round_number=g.current_round and player_id=actor),'round_closed',closed,'winner',case when closed then r.winner else null end,'scores',scores)||case when closed then jsonb_build_object('correct_choice_id',q.correct_choice_id,'explanation',q.explanation) else '{}'::jsonb end;end $$;
create function public.cancel_unfriended_games() returns trigger language plpgsql security definer set search_path='' as $$begin if TG_OP='DELETE' or new.status<>'accepted' then update public.game_rooms set status='cancelled' where least(host_id,guest_id)=old.user_low and greatest(host_id,guest_id)=old.user_high and status in('waiting','ready','active');end if;if TG_OP='DELETE' then return old;end if;return new;end $$;
create trigger cancel_friend_games after update or delete on public.friendships for each row execute function public.cancel_unfriended_games();
revoke all on function public.validate_game_bank(),public.cancel_unfriended_games() from public,anon,authenticated;
revoke all on function public.publish_game_question_job(uuid,uuid,integer,integer) from public,anon,authenticated;grant execute on function public.publish_game_question_job(uuid,uuid,integer,integer) to service_role;
do $$declare f record;begin for f in select oid::regprocedure sig from pg_proc where pronamespace='public'::regnamespace and proname in('create_game','ready_game','start_game','answer_game','next_game','game_snapshot') loop execute format('revoke all on function %s from public,anon',f.sig);execute format('grant execute on function %s to authenticated,service_role',f.sig);end loop;end $$;
commit;
